const assert=require('node:assert/strict');const cp=require('node:child_process');const fs=require('node:fs');const ts=require('typescript');
const file='src/lib/miden/back/main.test.ts';const base='b6713c0e26b7e513104d2da5f806d76bf0c7b56c';const previous=cp.execFileSync('git',['show',base+':'+file],{encoding:'utf8'});const current=fs.readFileSync(file,'utf8');
const printer=ts.createPrinter({removeComments:true});function split(text){const sf=ts.createSourceFile(file,text,ts.ScriptTarget.Latest,true,ts.ScriptKind.TS);assert.equal(sf.parseDiagnostics.length,0);const imports=[],rest=[];for(const statement of sf.statements){const output=printer.printNode(ts.EmitHint.Unspecified,statement,sf);(ts.isImportDeclaration(statement)?imports:rest).push(output)}return {imports:imports.sort(),rest}}
assert.deepEqual(split(previous),split(current));assert.deepEqual(cp.execFileSync('git',['diff','--name-only',base,'93a5e03e23723312707cdeee5ce7ce2c04472dc9'],{encoding:'utf8'}).trim().split('\n'),[file]);console.log('Production files identical; main test import multiset and remaining syntax tree identical');
